PAGE = dict(
    slug='y_limit_method',
    title='Pane::y_limit_method',
    signature='Pane& Pane::y_limit_method(LimitMethod method) noexcept',
    intro='Chooses how the y axis range is computed while it is fitted automatically, that is, while no range has been set with [`y_limits`](y_limits.md). `LimitMethod::TickAligned` (the default) widens the data range to round tick values so the axis starts and ends on clean numbers; `LimitMethod::Tight` uses the data range as it is, so the data touches the edges; `LimitMethod::Padded` adds a margin around the data so that no point lies on the edge. See [`LimitMethod`](../types/LimitMethod.md).\n\nThe method is stored in `y_axis().limit_method` and is kept when the axis is switched between manual and automatic, so [`auto_y`](auto_y.md) returns to the method that was chosen. With a manual range the method has no effect at all. The call never throws.',
    parameters='**method** (`LimitMethod`)\n    `TickAligned`, `Tight` or `Padded`.',
    returns='`Pane&`\n    The same pane, for chaining.',
    examples=[
        dict(id='readback', text='The default is `TickAligned` (0). `Tight` is 1 and `Padded` is 2; each call is read back, and the last call wins.',
             code='auto fig = studio("y_method_readback");\nauto& pane = fig.pane2("p");\npane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{2, 5, 4, 3});\nstd::cout << "new axis: " << static_cast<int>(pane.y_axis().limit_method) << "\\n";\nfor (LimitMethod m : {LimitMethod::Tight, LimitMethod::Padded, LimitMethod::TickAligned}) {\n  pane.y_limit_method(m);\n  std::cout << "set " << static_cast<int>(m) << ", read " << static_cast<int>(pane.y_axis().limit_method) << "\\n";\n}\nfig.save_svg("figure.svg");'),
        dict(id='tick_aligned', text='`TickAligned`, the default. The range is widened to round tick values, so the axis starts and ends on clean numbers; the ticks of the data 2.3 to 6.2 run from 2 to 7.',
             code='auto fig = studio("y_method_aligned");\nauto& pane = fig.pane2("p");\npane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{2.3, 4.7, 3.1, 6.2});\npane.x_tick_labels(false);\npane.z_tick_labels(false);\npane.y_limit_method(LimitMethod::TickAligned);\nauto texts = [](const std::string& svg) {\n  std::string out;\n  for (std::size_t at = svg.find("<text"); at != std::string::npos; at = svg.find("<text", at + 1)) {\n    const auto gt = svg.find(\'>\', at);\n    out += svg.substr(gt + 1, svg.find("</text>", gt) - gt - 1) + " ";\n  }\n  return out;\n};\nstd::cout << texts(fig.to_svg()) << "\\n";\nfig.save_svg("figure.svg");'),
        dict(id='tight', text='`Tight`. The range hugs the data, so the data touches the edges of the plot area and the end ticks sit inside it.',
             code='auto fig = studio("y_method_tight");\nauto& pane = fig.pane2("p");\npane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{2.3, 4.7, 3.1, 6.2});\npane.x_tick_labels(false);\npane.z_tick_labels(false);\npane.y_limit_method(LimitMethod::Tight);\nauto texts = [](const std::string& svg) {\n  std::string out;\n  for (std::size_t at = svg.find("<text"); at != std::string::npos; at = svg.find("<text", at + 1)) {\n    const auto gt = svg.find(\'>\', at);\n    out += svg.substr(gt + 1, svg.find("</text>", gt) - gt - 1) + " ";\n  }\n  return out;\n};\nstd::cout << texts(fig.to_svg()) << "\\n";\nfig.save_svg("figure.svg");'),
        dict(id='padded', text='`Padded`. A margin is added around the data, so no point sits on the edge; the three methods give three different figures.',
             code='auto build = [&](LimitMethod method) {\n  auto fig = studio("y_method_padded");\n  auto& pane = fig.pane2("p");\n  pane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{2.3, 4.7, 3.1, 6.2});\n  pane.y_limit_method(method);\n  return fig;\n};\nstd::cout << "TickAligned vs Tight: " << (build(LimitMethod::TickAligned).to_svg() != build(LimitMethod::Tight).to_svg()) << ", Tight vs Padded: " << (build(LimitMethod::Tight).to_svg() != build(LimitMethod::Padded).to_svg()) << "\\n";\nbuild(LimitMethod::Padded).save_svg("figure.svg");'),
        dict(id='manual', text='No effect with a manual range. Once `limits` sets a range the method is never consulted: the three methods give byte-identical figures.',
             code='auto build = [&](LimitMethod method) {\n  auto fig = studio("y_method_manual");\n  auto& pane = fig.pane2("p");\n  pane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{2, 5, 4, 3});\n  pane.y_limits(Range1d{0.0, 10.0});\n  pane.y_limit_method(method);\n  return fig.to_svg();\n};\nstd::cout << "all equal: " << (build(LimitMethod::TickAligned) == build(LimitMethod::Tight) && build(LimitMethod::Tight) == build(LimitMethod::Padded)) << "\\n";\nauto fig = studio("y_method_manual_out");\nauto& pane = fig.pane2("p");\npane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{2, 5, 4, 3});\nfig.save_svg("figure.svg");'),
    ],
    notes='- `noexcept`. The method concerns the automatic range only; the displayed range of a manual axis is exactly the range that was set.',
    see=['[`Pane::y_limits`](y_limits.md): a manual range, which overrides the method.', '[`Pane::auto_y`](auto_y.md): back to automatic fitting.', '[`LimitMethod`](../types/LimitMethod.md): the values.', '[`Pane::x_limit_method`](x_limit_method.md): the same setting for the x axis.', '[`Pane::z_limit_method`](z_limit_method.md): the same setting for the z axis.'],
)
